  <p>霍启在星辰，不同于其他人的盲目乐观，他皱着眉看向数据，《天衡》现在收视率虽然不如他们，但它的收视率却渐渐在上升，反观他们的，收视率似乎整体没有变化，可却有着下降的趋势。</p>
